#!/usr/bin/env python3
from __future__ import annotations

import json
import os
import shutil
import subprocess
from datetime import datetime, timezone
from pathlib import Path

ROOT = Path(os.environ.get('EDARSAHUB_ROOT', '/app')).resolve()
GIT = ROOT / '.git'
QUEUE = GIT / 'universal-worker-queue'
GUARD_STATE = GIT / 'agent-guard' / 'state'
TARGETS = (
    'worker-p1-result-publisher-idempotency-20260827',
    'worker-worker-canonical-python-runtime-20260826',
    'worker-worker-concurrent-producer-branches-v1-20260827',
)
ACTIVE_DIRS = ('pending', 'processing')


def _run(args):
    return subprocess.run(args, cwd=ROOT, text=True, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, check=False)


def _active(job_id):
    return any((QUEUE / directory / f'{job_id}.json').exists() for directory in ACTIVE_DIRS)


def _proc_mentions(job_id):
    proc = Path('/proc')
    if not proc.is_dir():
        return False
    for entry in proc.iterdir():
        if not entry.name.isdigit():
            continue
        try:
            cmdline = (entry / 'cmdline').read_bytes().replace(b'\x00', b' ').decode('utf-8', 'ignore')
        except (OSError, PermissionError):
            continue
        if job_id in cmdline:
            return True
    return False


def _worktrees():
    result = _run(['git', 'worktree', 'list', '--porcelain'])
    if result.returncode != 0:
        raise RuntimeError('WORKTREE_LIST_FAILED:' + result.stdout[-1000:])
    items = []
    current = {}
    for line in result.stdout.splitlines() + ['']:
        if not line:
            if current:
                items.append(current)
                current = {}
            continue
        key, _, value = line.partition(' ')
        current[key] = value
    return items


def _matching_state_files(job_id):
    matches = []
    if not GUARD_STATE.is_dir():
        return matches
    for path in GUARD_STATE.rglob('*'):
        if not path.is_file():
            continue
        try:
            text = path.read_text(encoding='utf-8', errors='ignore')
        except OSError:
            continue
        if job_id in path.name or job_id in text:
            matches.append(path)
    return matches


def reconcile(apply=False):
    evidence = {
        'schema': 'edarsahub.agent-guard-orphan-reconcile.v1',
        'generated_at_utc': datetime.now(timezone.utc).isoformat(),
        'apply': bool(apply),
        'targets': {},
    }
    worktrees = _worktrees()
    stamp = datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ')
    quarantine = GUARD_STATE / 'orphaned' / stamp

    for job_id in TARGETS:
        active = _active(job_id)
        process_alive = _proc_mentions(job_id)
        if active or process_alive:
            raise RuntimeError(f'FAIL_CLOSED_ACTIVE_OWNER:{job_id}:queue={active}:process={process_alive}')

        branches = {f'refs/heads/agent/worker/{job_id}', f'refs/heads/agent/{job_id}'}
        matched_worktrees = [item for item in worktrees if item.get('branch') in branches or job_id in item.get('worktree', '')]
        state_files = _matching_state_files(job_id)
        item = {
            'active_queue': active,
            'process_alive': process_alive,
            'worktrees': [x.get('worktree') for x in matched_worktrees],
            'state_files': [str(x) for x in state_files],
            'actions': [],
        }

        if apply:
            for wt in matched_worktrees:
                directory = wt.get('worktree')
                if directory and Path(directory).resolve() != ROOT:
                    result = _run(['git', 'worktree', 'remove', '--force', directory])
                    if result.returncode != 0:
                        raise RuntimeError(f'WORKTREE_REMOVE_FAILED:{job_id}:{result.stdout[-1000:]}')
                    item['actions'].append('worktree_removed:' + directory)

            for branch in (f'agent/worker/{job_id}', f'agent/{job_id}'):
                exists = _run(['git', 'show-ref', '--verify', '--quiet', f'refs/heads/{branch}'])
                if exists.returncode == 0:
                    deleted = _run(['git', 'branch', '-D', branch])
                    if deleted.returncode != 0:
                        raise RuntimeError(f'BRANCH_DELETE_FAILED:{job_id}:{deleted.stdout[-1000:]}')
                    item['actions'].append('branch_deleted:' + branch)

            for source in state_files:
                relative = source.relative_to(GUARD_STATE)
                target = quarantine / relative
                target.parent.mkdir(parents=True, exist_ok=True)
                shutil.move(str(source), str(target))
                item['actions'].append('state_quarantined:' + str(relative))

        evidence['targets'][job_id] = item

    if apply:
        _run(['git', 'worktree', 'prune'])
    return evidence


if __name__ == '__main__':
    print(json.dumps(reconcile(apply=True), ensure_ascii=False, indent=2))
